// Override the Quick Entry creation for Company
frappe.provide('frappe.ui.form');

// Store original quick entry function
let original_quick_entry = frappe.ui.form.make_quick_entry;

// Override quick entry for Company doctype
frappe.ui.form.make_quick_entry = function(doctype, after_insert, init_callback, doc, force) {
    if (doctype === 'Company') {
        return original_quick_entry.call(this, doctype, after_insert, function(dialog) {
            // Original init callback
            if (init_callback) {
                init_callback(dialog);
            }
            
            // Add our custom handlers
            setup_company_quick_entry_handlers(dialog);
            
        }, doc, force);
    } else {
        return original_quick_entry.call(this, doctype, after_insert, init_callback, doc, force);
    }
};

// Setup handlers for Company Quick Entry
function setup_company_quick_entry_handlers(dialog) {
    // Wait for dialog to be fully rendered
    setTimeout(function() {
        // Find company name field in the dialog
        let company_name_field = dialog.fields_dict.company_name;
        
        if (company_name_field && company_name_field.$input) {
            console.log('Quick Entry: Company name field found');
            
            // Add event listener
            company_name_field.$input.on('input keyup blur', function(e) {
                let company_name = e.target.value.trim();
                console.log('Quick Entry: Company name changed to:', company_name);
                
                if (company_name) {
                    let abbr = generate_abbr(company_name);
                    console.log('Quick Entry: Generated abbr:', abbr);
                    
                    // Find unique abbreviation for quick entry
                    find_unique_abbr_quick_entry(dialog, abbr, company_name, 1);
                }
            });
        } else {
            console.log('Quick Entry: Company name field not found, trying alternative method');
            
            // Alternative method - direct jQuery
            let $company_input = dialog.$wrapper.find('[data-fieldname="company_name"] input');
            if ($company_input.length) {
                console.log('Quick Entry: Found company input via jQuery');
                
                $company_input.on('input keyup blur', function() {
                    let company_name = $(this).val().trim();
                    console.log('Quick Entry: Company name (jQuery):', company_name);
                    
                    if (company_name) {
                        let abbr = generate_abbr(company_name);
                        find_unique_abbr_quick_entry(dialog, abbr, company_name, 1);
                    }
                });
            }
        }
    }, 1000); // Increased timeout to ensure dialog is ready
}

// Find unique abbreviation for Quick Entry
function find_unique_abbr_quick_entry(dialog, abbr, company_name, attempt) {
    frappe.call({
        method: 'frappe.client.get_count',
        args: {
            doctype: 'Company',
            filters: {
                'abbr': abbr
            }
        },
        callback: function(r) {
            if (r.message > 0) {
                // Abbreviation exists, generate next unique option
                let new_abbr = generate_unique_abbr(company_name, attempt);
                
                if (new_abbr !== abbr && attempt < 10) {
                    find_unique_abbr_quick_entry(dialog, new_abbr, company_name, attempt + 1);
                } else {
                    let fallback_abbr = generate_abbr(company_name) + attempt;
                    find_unique_abbr_quick_entry(dialog, fallback_abbr, company_name, attempt + 1);
                }
            } else {
                // Found unique abbreviation - set in dialog
                console.log('Quick Entry: Setting abbr to:', abbr);
                
                if (dialog.fields_dict.abbr) {
                    dialog.set_value('abbr', abbr);
                } else {
                    // Fallback jQuery method
                    dialog.$wrapper.find('[data-fieldname="abbr"] input').val(abbr);
                }
                
                if (attempt > 1) {
                    frappe.show_alert('Abbreviation set to: ' + abbr, 3);
                }
            }
        }
    });
}

// Recursive function to find truly unique abbreviation for main form
function find_unique_abbr(frm, abbr, company_name, attempt) {
    frappe.call({
        method: 'frappe.client.get_count',
        args: {
            doctype: 'Company',
            filters: {
                'abbr': abbr,
                'name': ['!=', frm.doc.name || '']
            }
        },
        callback: function(r) {
            if (r.message > 0) {
                let new_abbr = generate_unique_abbr(company_name, attempt);
                
                if (new_abbr !== abbr) {
                    find_unique_abbr(frm, new_abbr, company_name, attempt + 1);
                } else {
                    let fallback_abbr = generate_abbr(company_name) + attempt;
                    find_unique_abbr(frm, fallback_abbr, company_name, attempt + 1);
                }
            } else {
                frm.set_value('abbr', abbr);
                if (attempt > 1) {
                    frappe.show_alert('Abbreviation set to: ' + abbr, 3);
                }
            }
        }
    });
}

function generate_abbr(company_name) {
    let words = company_name.split(' ');
    let abbr = '';
    
    if (words.length > 1) {
        for (let i = 0; i < words.length; i++) {
            if (words[i].length > 0) {
                abbr += words[i].charAt(0).toUpperCase();
            }
        }
    } else {
        abbr = company_name.substring(0, Math.min(4, company_name.length)).toUpperCase();
    }
    
    return abbr;
}

function generate_unique_abbr(company_name, attempt) {
    let words = company_name.split(' ');
    
    if (attempt === 1 && words.length > 1 && words[0].length >= 2) {
        let abbr = words[0].substring(0, 2).toUpperCase();
        for (let i = 1; i < words.length; i++) {
            if (words[i].length > 0) {
                abbr += words[i].charAt(0).toUpperCase();
            }
        }
        return abbr;
    }
    
    if (attempt === 2 && words.length > 1 && words[0].length >= 3) {
        let abbr = words[0].substring(0, 3).toUpperCase();
        for (let i = 1; i < Math.min(words.length, 2); i++) {
            if (words[i].length > 0) {
                abbr += words[i].charAt(0).toUpperCase();
            }
        }
        return abbr;
    }
    
    if (attempt === 3) {
        let consonants = company_name.replace(/[aeiouAEIOU\s]/g, '').substring(0, 4).toUpperCase();
        if (consonants.length >= 2) {
            return consonants;
        }
    }
    
    return generate_abbr(company_name) + attempt;
}

