frappe.ui.form.on('Staffing Plan', {
    refresh: function(frm) {
        // Initialize current index if not set
        if (!frm.doc.__current_job_opening_index) {
            frm.doc.__current_job_opening_index = 0;
        }
        
        // Add custom button only if document is saved and has staffing details
        if (frm.doc.docstatus === 1 && frm.doc.staffing_details && frm.doc.staffing_details.length > 0) {
            frm.add_custom_button(__('Create Job Opening'), function() {
                create_job_opening_from_staffing(frm);
            }, __('Actions'));
            
            // Add button to reset index (optional)
            frm.add_custom_button(__('Reset Job Opening Index'), function() {
                frm.doc.__current_job_opening_index = 0;
                frappe.show_alert({
                    message: __('Job Opening index reset to first position'),
                    indicator: 'green'
                });
            }, __('Actions'));
        }
    }
});


function create_job_opening_from_staffing(frm) {
    let current_index = frm.doc.__current_job_opening_index || 0;
    let staffing_details = frm.doc.staffing_details || [];

    if (staffing_details.length === 0) {
        frappe.msgprint({
            title: __('No Staffing Details'),
            message: __('Please add staffing details before creating job openings'),
            indicator: 'orange'
        });
        return;
    }

    if (current_index >= staffing_details.length) {
        frappe.msgprint({
            title: __('All Positions Processed'),
            message: __('Job openings have been created for all positions. Index will reset to first position.'),
            indicator: 'blue'
        });
        current_index = 0;
        frm.doc.__current_job_opening_index = 0;
    }

    let current_row = staffing_details[current_index];

    frappe.show_alert({
        message: __('Creating Job Opening for: {0} ({1}/{2})', [
            current_row.designation,
            current_index + 1,
            staffing_details.length
        ]),
        indicator: 'blue'
    });

    // ✅ Job Title stays clean
    let clean_title = current_row.designation;

    // ✅ Route made unique (designation + staffing plan row id)
    let unique_route = `${frappe.slug(current_row.designation)}-${current_row.name}`;

    frappe.new_doc('Job Opening', {
        company: frm.doc.company,
        department: frm.doc.department,
        job_title: clean_title,  // stays neat
        route: unique_route,     // hidden field ensures uniqueness
        no_of_positions: current_row.vacancies || current_row.number_of_positions,
        status: 'Open',
        custom_staffing_plan: frm.doc.name,
        custom_staffing_plan_row: current_row.name,
        currency: frm.doc.currency || frappe.defaults.get_default('Currency'),
        lower_range: current_row.estimated_cost_per_position || 0,
        upper_range: current_row.estimated_cost_per_position
            ? (current_row.estimated_cost_per_position * 1.2)
            : 0,
        description: `Job opening created from Staffing Plan: ${frm.doc.name}
Position: ${current_row.designation}
Vacancies: ${current_row.vacancies || current_row.number_of_positions}
Estimated Cost: ${current_row.estimated_cost_per_position || 'Not specified'}`
    });

    // Set designation after form loads
    setTimeout(() => {
        if (cur_frm && cur_frm.doctype === 'Job Opening') {
            cur_frm.set_value('designation', current_row.designation);
            cur_frm.refresh_field('designation');
        }
    }, 1000);

    frm.doc.__current_job_opening_index = current_index + 1;

    setTimeout(() => {
        frappe.show_alert({
            message: __('Job Opening form opened with pre-filled data'),
            indicator: 'green'
        });
    }, 500);
}

