        if (frm.doc.custom_full_name) {
            // Let the normal link field behavior handle company fetching
            setTimeout(() => {
                customize_link_field_behavior(frm);
            }, 500);
        }
    }
});

function customize_link_field_behavior(frm) {
    let field = frm.fields_dict.custom_full_name;
    
    if (!field || !field.$input) return;
    
    // Store the original awesomplete instance
    let original_setup = field.setup_awesomplete;
    
    // Override the awesomplete setup to add custom behavior
    field.setup_awesomplete = function() {
        // Call original setup first
        if (original_setup) {
            original_setup.call(this);
        }
        
        // Now customize the behavior
        if (this.awesomplete) {
            // Override the item selection
            this.awesomplete.replace = function(suggestion) {
                // Check if this suggestion exists in Contact
                frappe.call({
                    method: 'frappe.client.get_value',
                    args: {
                        doctype: 'Contact',
                        filters: {'full_name': suggestion.value || suggestion},
                        fieldname: ['name', 'company_name']
                    },
                    callback: function(r) {
                        if (r.message) {
                            // Contact exists - set the value and let auto-fetch work
                            frm.set_value('custom_full_name', suggestion.value || suggestion);
                        } else {
                            // Contact doesn't exist - set value but don't trigger link behavior
                            frm.doc.custom_full_name = suggestion.value || suggestion;
                            field.$input.val(suggestion.value || suggestion);
                            frm.dirty();
                        }
                    }
                });
            };
        }
    };
    
    // Re-setup the awesomplete
    field.setup_awesomplete();
    
    // Override the link button click behavior
    setTimeout(() => {
        let link_btn = field.$input_area.find('.link-btn');
        if (link_btn.length > 0) {
            link_btn.off('click').on('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                
                // Check if contact exists before opening form
                if (frm.doc.custom_full_name) {
                    frappe.call({
                        method: 'frappe.client.get_value',
                        args: {
                            doctype: 'Contact',
                            filters: {'full_name': frm.doc.custom_full_name},
                            fieldname: ['name']
                        },
                        callback: function(r) {
                            if (r.message) {
                                // Contact exists - open the form
                                frappe.set_route('Form', 'Contact', r.message.name);
                            } else {
                                // Contact doesn't exist - show message
                                frappe.msgprint({
                                    title: __('Contact Not Found'),
                                    message: __('No contact found with name "{0}". You can continue typing to enter a custom name.', [frm.doc.custom_full_name]),
                                    indicator: 'orange'
                                });
                            }
                        }
                    });
                }
            });
        }
    }, 100);
}

