// Client Script for Lead DocType
// This script automatically breaks down custom_full_name and fills first_name, middle_name, last_name

frappe.ui.form.on('Lead', {
    // Trigger when custom_full_name field changes
    custom_full_name: function(frm) {
        if (frm.doc.custom_full_name) {
            breakdownFullName(frm);
        }
    },
    
    // Also trigger on form refresh in case the full name is already set
    refresh: function(frm) {
        if (frm.doc.custom_full_name && (!frm.doc.first_name && !frm.doc.middle_name && !frm.doc.last_name)) {
            breakdownFullName(frm);
        }
    }
});

function breakdownFullName(frm) {
    // Debug: Check what we're getting
    console.log('custom_full_name field value:', frm.doc.custom_full_name);
    
    let fullName = '';
    
    // Check if custom_full_name is a string (person's name) or a link to Contact
    if (typeof frm.doc.custom_full_name === 'string') {
        fullName = frm.doc.custom_full_name.trim();
    } else {
        // If it's a link field, we need to get the display value
        // This might be getting organization name instead of person name
        frappe.show_alert({
            message: 'Please enter the person\'s full name directly in the custom_full_name field',
            indicator: 'orange'
        });
        return;
    }
    
    if (!fullName) {
        return;
    }
    
    // Additional check: Skip if it looks like an organization name
    // Common organization indicators
    let orgIndicators = ['ltd', 'limited', 'inc', 'incorporated', 'corp', 'corporation', 
                        'llc', 'company', 'co.', 'pvt', 'private', 'solutions', 
                        'technologies', 'tech', 'services', 'consulting', 'group'];
    
    let lowerName = fullName.toLowerCase();
    let isOrganization = orgIndicators.some(indicator => lowerName.includes(indicator));
    
    if (isOrganization) {
        frappe.show_alert({
            message: 'This appears to be an organization name, not a person\'s name. Please enter the contact person\'s full name.',
            indicator: 'orange'
        });
        return;
    }
    
    // Split the full name by spaces
    let nameParts = fullName.split(/\s+/);
    
    // Only proceed if we don't already have name parts filled
    if (frm.doc.first_name || frm.doc.middle_name || frm.doc.last_name) {
        frappe.confirm(
            'Name fields already have values. Do you want to overwrite them?',
            function() {
                fillNameParts(frm, nameParts);
            }
        );
    } else {
        fillNameParts(frm, nameParts);
    }
}

function fillNameParts(frm, nameParts) {
    // Clear existing values first
    frm.set_value('first_name', '');
    frm.set_value('middle_name', '');
    frm.set_value('last_name', '');
    
    if (nameParts.length === 1) {
        // Only one name - assume it's the first name
        frm.set_value('first_name', nameParts[0]);
        
    } else if (nameParts.length === 2) {
        // Two names - first and last
        frm.set_value('first_name', nameParts[0]);
        frm.set_value('last_name', nameParts[1]);
        
    } else if (nameParts.length >= 3) {
        // Three or more names - first, middle(s), and last
        frm.set_value('first_name', nameParts[0]);
        frm.set_value('last_name', nameParts[nameParts.length - 1]);
        
        // Join all middle names with spaces
        let middleNames = nameParts.slice(1, -1).join(' ');
        frm.set_value('middle_name', middleNames);
    }
    
    // Show success message
    frappe.show_alert({
        message: `Name split: ${frm.doc.first_name} ${frm.doc.middle_name || ''} ${frm.doc.last_name || ''}`.replace(/\s+/g, ' '),
        indicator: 'green'
    });
}

