frappe.ui.form.on('Lead', {
    onload: function(frm) {
        // Set default stage for new documents
        if (frm.is_new() && !frm.doc.custom_stage) {
            frm.set_value('custom_stage', 'Prospecting');
        }
    },
    
    refresh: function(frm) {
        handle_contract_restrictions(frm);
    },
    
    custom_stage: function(frm) {
        handle_contract_restrictions(frm);
    }
});

function handle_contract_restrictions(frm) {
    // Define stages that come after Contract (including Contract itself)
    var post_contract_stages = ['Contract', 'Onboarding', 'Onboarded', 'Follow-Up / Relationship Management'];
    
    if (post_contract_stages.includes(frm.doc.custom_stage)) {
        // Make all fields readonly except custom_stage for Contract and post-Contract stages
        make_fields_readonly(frm, true);
        
        // Set limited stage options for Contract and beyond
        frm.set_df_property('custom_stage', 'options', [
            'Contract',
            'Onboarding', 
            'Onboarded',
            'Follow-Up / Relationship Management'
        ].join('\n'));
        
        frm.refresh_field('custom_stage');
        
    } else {
        // Make fields editable for pre-Contract stages
        make_fields_readonly(frm, false);
        
        // Reset all stage options for pre-Contract stages
        frm.set_df_property('custom_stage', 'options', [
            'Prospecting',
            'Qualified', 
            'Proposal',
            'Contract',
            'Onboarding',
            'Onboarded',
            'Follow-Up / Relationship Management'
        ].join('\n'));
        
        frm.refresh_field('custom_stage');
    }
}

function make_fields_readonly(frm, readonly_status) {
    // List of all important fields that should be readonly in Contract stage
    var field_list = [
        'naming_series', 'salutation', 'first_name', 'middle_name', 'last_name',
        'custom_full_name', 'type', 'lead_name', 'job_title', 'gender', 
        'custom_phone_number', 'custom_offerings', 'custom_expected_close_date',
        'lead_owner', 'status', 'customer', 'request_type', 'custom_email_address',
        'custom_lead_owner_name', 'company_name', 'no_of_employees', 'territory',
        'email_id', 'custom_organization_name', 'utm_source', 'annual_revenue',
        'market_segment', 'industry', 'city', 'fax', 'website', 'state', 'country',
        'custom_estimated_hiring_', 'custom_average_salary', 'custom_fee', 
        'custom_deal_value', 'mobile_no', 'whatsapp_no', 'phone', 'phone_ext',
        'utm_content', 'utm_campaign', 'utm_medium', 'qualification_status',
        'qualified_by', 'qualified_on', 'company', 'language', 'image', 'title',
        'disabled', 'unsubscribed', 'blog_subscriber', 'custom_lead_notes'
    ];
    
    field_list.forEach(function(fieldname) {
        if (frm.get_field(fieldname)) {
            frm.set_df_property(fieldname, 'read_only', readonly_status);
        }
    });
    
    // Always keep custom_stage editable
    frm.set_df_property('custom_stage', 'read_only', 0);
}
